LEVEL = 1
CFG = {1: {"v": 1}, 2: {"v": 2}, 3: {"v": 3}}
keys = {"k1": "K1", "k2": "K2", "k3": "K3"}
current = "k%d" % CFG[LEVEL]["v"]
store = {"rec1": ("k1", "ct1"), "rec2": (current, "ct2")}
def decrypt(rec):
    k, _ = store[rec]
    return k in keys  # dual-read: old keys still work during rotation
print("current:", current, "| rec1 decrypt:", decrypt("rec1"), "| rec2 decrypt:", decrypt("rec2"))

